from __future__ import annotations

from kicad_lib_tools.config import LibraryConfig
from kicad_lib_tools.libraries_md import render


def test_render_lists_top_level_symbols_with_descriptions(repo: LibraryConfig) -> None:
    (repo.symbol_path / "GS_Test.kicad_sym").write_text(
        """\
(kicad_symbol_lib
	(symbol "Part"
		(property "Description" "A test part"
		)
		(symbol "Part_0_1"
		)
	)
	(symbol "Bare"
	)
)
""",
        encoding="utf-8",
    )

    assert render(repo) == (
        "# GS KiCad Libraries\n"
        "\n"
        "<!-- Auto-generated by `kicad-lib libraries-md`; do not edit -->\n"
        "\n"
        "| Library | Components |\n"
        "|---|---|\n"
        "| [GS_Test](#gs-test) | 2 |\n"
        "\n"
        "## GS_Test\n"
        "\n"
        "- **Part** — A test part\n"
        "- **Bare**\n"
        "\n"
    )
